def F(n,b=False):return ImageFont.truetype('C:/Windows/Fonts/arialbd.ttf' if b else 'C:/Windows/Fonts/arial.ttf',n)
def make(name,page,subtitle,cards,marks=[]):
 im=Image.new('RGB',(1440,860),'#F5F7FA');d=ImageDraw.Draw(im);d.rectangle((0,0,242,860),fill='#17212B');d.text((20,24),'Procurement control',font=F(18,1),fill='white');d.text((20,52),'Контроль закупки',font=F(12),fill='#B7C4D3');y=100
 for s in ['Дашборд','Сравнение RRFQ','Аналитика поставщиков','Контроль закупки','Задачи','Напоминания','База квот','Компэл Парсер','Поиск цен','Настройки','История']:
  if s==page:d.rounded_rectangle((12,y-7,230,y+27),6,fill='#294560');col='white'
  else:col='#B7C4D3'
  d.text((25,y),s,font=F(14,s==page),fill=col);y+=44
 d.rectangle((242,0,1440,63),fill='white');d.line((242,63,1440,63),fill='#D9E0EA');d.text((270,19),page,font=F(21,1),fill='#172B4D');d.text((270,76),subtitle,font=F(14),fill='#667085')
 for box,h,rows in cards:
  d.rounded_rectangle(box,12,fill='white',outline='#D9E0EA');d.text((box[0]+18,box[1]+16),h,font=F(16,1),fill='#172B4D');yy=box[1]+52
  for row in rows:d.text((box[0]+18,yy),row,font=F(13),fill='#172B4D');yy+=28
 for n,x,y,label in marks:
  d.ellipse((x-14,y-14,x+14,y+14),fill='#1967D2');d.text((x-4,y-10),str(n),font=F(14,1),fill='white');d.text((x+22,y-9),label,font=F(13,1),fill='#1967D2')
 p=shots/name;im.save(p);return p
